\begin{example}[The Euclidean Group]
\label{ex:7-32}




\dcref{ch7:7.32}
The Euclidean group is $\mathrm E(n)=\mathbb R^n\rtimes\mathrm O(n)$ with
\[
(b,A)(b',A')=(b+Ab',AA'),\qquad (b,A)\cdot x=b+Ax.
\]
This action preserves lines, distances, and angles.
\end{example}

